  stations = {
    ["01-1"] = {name="Долина Испытаний", tips={{k="交通", text="Старт другой расы: идите по дороге Дуротара на юг, с восточного входа в Долину Испытаний найдите Калтунка. Полный маршрут см. в начале."}, {k="取捨", text="Стоит выполнить «Брошенное оружие», «Ленивые батраки» и два квеста в Гроте Пылающего Клинка. Цели можно объединить в два захода."}, {k="取捨", text="Сначала завершите квест про беса (Злобные фамильяры/Злобные фамильяры), затем у той же Зуриты Востроглазой возьмите «Медальон Пылающего Клинка». Только чернокнижники.", s={{"Сначала завершите квест про беса (Злобные фамильяры/Злобные фамильяры), затем у той же Зуриты Востроглазой возьмите «Медальон Пылающего Клинка». Только чернокнижники.", {class={"WARLOCK"}}}}}, {k="提醒", text="Если ниже 6 уровня, по пути в деревню Сен'джин бейте пятнистых вепрей, рабочих скорпидов или злобных фамильяров.", s={{"Если ниже 6 уровня, по пути в деревню Сен'джин бейте пятнистых вепрей, рабочих скорпидов или злобных фамильяров"}}}}, danger={[1]="Поворот в Гроте Пылающего Клинка перекрывается с местами появления бесов. Перед тем как брать кирку, зачистите вход и оставьте путь к отступлению."}, grind={[1]={mob="Пятнистый вепрь", note="Плотная группа обычных, в основном нейтральных мобов. Вытягивайте по одному. Северная поляна Долины Испытаний, на уровнях 1-2 далее «Кабаньи клыки»."}, [2]={mob="Рабочий скорпид", note="Плотная группа обычных, в основном нейтральных мобов. Вытягивайте по одному. К северо-западу от Логова, попутно с «Жалами скорпидов»."}, [3]={mob="Злобный фамилиар", note="Плотная группа обычных мобов, у входа легко навлечь лишних. Сначала бейте тех, что снаружи. Район Грота Пылающего Клинка, до ухода из долины добейте 6 уровень."}}, supply={[1]={npc="Рарк"}, [2]={npc="Зляк"}, [3]={npc="Дуокна"}}, steps={[1]={npc="Калтунк", tgt="Калтунк"}, [2]={npc="Горнек", tgt="Горнек"}, [3]={npc="Подарочный сертификат долины Испытаний", npcObj=true, tag="Необязательно, Требуется внутриигровая проверка", desc="Берите, только если у вас есть подарочный сертификат Долины Испытаний. Подарочный сертификат - стартовый предмет в сумке персонажа исходной расы. Щелкните по нему правой кнопкой мыши, точки получения на карте нет."}, [4]={npc="Магга", tgt="Магга", tag="Необязательно", desc="Берите, только если у вас есть подарочный сертификат Долины Испытаний."}, [5]={npc="Горнек", tgt="Горнек"}, [6]={npc="Горнек", tgt="Горнек"}, [7]={hint="Убейте 10 пятнистых вепрей и вернитесь в Логово к Горнеку."}, [8]={hint="Добудьте 6 |4комплект:комплекта:комплектов; брошенного тренировочного оружия и вернитесь к Кзану Шипорубу в Логово."}, [9]={npc="Горнек", tgt="Горнек"}, [10]={npc="Кзан Шипоруб", tgt="Кзан Шипоруб"}, [11]={npc="Горнек", tgt="Горнек"}, [12]={npc="Галгар", tgt="Галгар"}, [13]={npc="Штейгер Тазз'рил", tgt="Штейгер Тазз'рил"}, [14]={npc="Зурита Востроглазая", tgt="Зурита Востроглазая"}, [15]={text="Сначала зачистите стартовую долину, затем идите к пещере на севере."}, [16]={hint="Добудьте 10 хвостов рабочих скорпидов и принесите их в Логово Горнеку."}, [17]={hint="Принесите Галгару 10 плодов кактуса."}, [18]={hint="Проучите ленивых батраков дубинкой старшины. Разбудите 5 батраков, потом верните дубинку штейгеру Тазз'рилу в долине Испытаний.", desc="Используйте дубинку, которую дает бригадир, на спящих батраках: достаточно разбудить пятерых."}, [19]={hint="Убейте 12 злобных фамильяров и вернитесь к Зурите Востроглазой, которая ждет вас у Логова.", desc="Чернокнижникам: вместо этого идите по ветке Рузан о призыве беса, см. классовые квесты."}, [20]={npc="Хана'зуа", tgt="Хана'зуа", tag="Необязательно"}, [21]={hint="Убейте Саркота и принесите его коготь Хана'зуа.", tag="Необязательно"}, [22]={npc="Хана'зуа", tgt="Хана'зуа", tag="Необязательно"}, [23]={npc="Хана'зуа", tgt="Хана'зуа", tag="Необязательно"}, [24]={hint="Расскажите Горнеку о том, что Хана'зуа в беде.", tag="Необязательно"}, [25]={npc="Горнек", tgt="Горнек", tag="Необязательно"}, [26]={npc="Горнек", tgt="Горнек"}, [27]={npc="Галгар", tgt="Галгар"}, [28]={npc="Штейгер Тазз'рил", tgt="Штейгер Тазз'рил"}, [29]={npc="Зурита Востроглазая", tgt="Зурита Востроглазая"}, [30]={npc="Штейгер Тазз'рил", tgt="Штейгер Тазз'рил"}, [31]={npc="Зурита Востроглазая", tgt="Зурита Востроглазая"}, [32]={hint="Принесите штейгеру Тазз'рилу его кирку.", desc="Кирка лежит в Гроте Пылающего Клинка, берите ее тем же заходом, что и медальон."}, [33]={hint="Принесите медальон Пылающего Клинка Зурите Востроглазой, стоящей у Логова.", desc="Найдите в пещере Йоррога Тень Проклятия и подберите Медальон Пылающего Клинка ×1."}, [34]={npc="Штейгер Тазз'рил", tgt="Штейгер Тазз'рил"}, [35]={npc="Зурита Востроглазая", tgt="Зурита Востроглазая"}, [36]={npc="Зурита Востроглазая", tgt="Зурита Востроглазая"}, [37]={npc="Потерянный дневник", npcObj=true, tag="Необязательно", desc="Потерянный дневник лежит рядом с Зуритой Востроглазой."}, [38]={npc="Горнек", tgt="Горнек", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [39]={hint="Прочтите пергамент и поговорите с Франгом в долине Испытаний.", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [40]={npc="Франг", tgt="Франг", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [41]={npc="Горнек", tgt="Горнек", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [42]={hint="Прочтите простую табличку и поговорите с Франгом в долине Испытаний.", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [43]={npc="Франг", tgt="Франг", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [44]={npc="Горнек", tgt="Горнек", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [45]={hint="Прочтите исписанный пергамент и поговорите с Руагом в долине Испытаний.", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [46