bj=true, tag="Необязательно"}, [131]={hint="Отнесите Аларика к замаскированной нише.", tag="Необязательно"}, [132]={npc="Пыльная полка", npcObj=true, tag="Необязательно"}, [133]={npc="Пыльная полка", npcObj=true, tag="Необязательно"}, [134]={npc="Верховный палач Хадрик", tgt="Верховный палач Хадрик"}, [135]={npc="Далар Ткач Рассвета", tgt="Далар Ткач Рассвета"}, [136]={npc="Далар Ткач Рассвета", tgt="Далар Ткач Рассвета"}, [137]={npc="Аптекарь Ренферрел", tgt="Аптекарь Ренферрел", tag="От 19 уровня, оставьте до Мельницы Таррен в Предгорьях Хилсбрада"}, [138]={text="Если в Подгороде есть квесты на сдачу, один раз слетайте из Гробницы в Подгород. Если нет, сразу используйте камень возвращения в Гробнице на следующем шаге."}, [139]={npc="Роли Андреан", tgt="Роли Андреан"}, [140]={npc="Мастер аптекарь Фаранелл", tgt="Мастер аптекарь Фаранелл"}, [141]={npc="Хранитель Бел'дугур", tgt="Хранитель Бел'дугур", tag="Подземелье, Необязательно"}, [142]={npc="Бетор Ледострел", tgt="Бетор Ледострел", tag="Необязательно"}, [143]={npc="Данита Морр", tgt="Данита Морр", desc="Достигнув 18 уровня в Гробнице в Серебряном бору, вернитесь из Гробницы в Тирисфальские леса и возьмите квест. После круга по северным фермам можно вернуться в форт."}, [144]={hint="Отправляйтесь в Гробницу в Серебряном бору и поговорите о пропавших предводителях Служителей Земли с Треваном Ролом.", desc="Достигнув 18 уровня в Гробнице в Серебряном бору, вернитесь из Гробницы в Тирисфальские леса и возьмите квест. После круга по северным фермам можно вернуться в форт."}, [145]={npc="Треван Рол", tgt="Треван Рол", desc="Достигнув 18 уровня в Гробнице в Серебряном бору, вернитесь из Гробницы в Тирисфальские леса и возьмите квест. После круга по северным фермам можно вернуться в форт."}, [146]={npc="Треван Рол", tgt="Треван Рол"}, [147]={hint="Поговорите со стражем смерти Балдреном о таинственных Служителях Земли, недавно проследовавших через Гробницу."}, [148]={npc="Страж смерти Балдрен", tgt="Страж смерти Балдрен"}, [149]={npc="Страж смерти Балдрен", tgt="Страж смерти Балдрен", desc="Можно делать вместе с квестами Острова Фенриса в Гробнице Серебряного бора."}, [150]={hint="Исследуйте остров Фенриса на востоке и узнайте о судьбе странствующих Служителей Земли.", desc="Можно делать вместе с квестами Острова Фенриса в Гробнице Серебряного бора."}, [151]={npc="Обугленные останки", npcObj=true, desc="Можно делать вместе с квестами Острова Фенриса в Гробнице Серебряного бора."}, [152]={npc="Обугленные останки", npcObj=true}, [153]={hint="Осмотрите крепость Фенриса на севере и поищите пропавшего участника отряда Служителей Земли."}, [154]={npc="Люмина Песнь Ветра", tgt="Люмина Песнь Ветра"}, [155]={npc="Люмина Песнь Ветра", tgt="Люмина Песнь Ветра"}, [156]={hint="Раздобудьте у гноллов из стаи Гнилошкуров ключ с острова Фенриса и с его помощью освободите Люмину Песнь Ветра."}, [157]={npc="Люмина Песнь Ветра", tgt="Люмина Песнь Ветра"}, [158]={npc="Люмина Песнь Ветра", tgt="Люмина Песнь Ветра"}, [159]={hint="Сопроводите Люмину Песнь Ветра и помогите ей сбежать из крепости Фенриса."}, [160]={npc="Люмина Песнь Ветра", tgt="Люмина Песнь Ветра"}, [161]={npc="Люмина Песнь Ветра", tgt="Люмина Песнь Ветра", desc="Следующий этап Клинок лунного поцелуя доступен только с 20 уровня после завершения."}, [162]={hint="Поговорите с Люминой Песнь Ветра в Гробнице.", desc="Следующий этап Клинок лунного поцелуя доступен только с 20 уровня после завершения."}, [163]={npc="Люмина Песнь Ветра", tgt="Люмина Песнь Ветра", desc="Следующий этап Клинок лунного поцелуя доступен только с 20 уровня после завершения."}, [164]={npc="Люмина Песнь Ветра", tgt="Люмина Песнь Ветра", tag="Необязательно", desc="Сначала сдайте Долг. На 20 уровне возьмите квест у Люмины Песнь Ветра, поговорите с Треваном Ролом и сохраните записи об оружии в сумке. Затем соберите три материала и вернитесь в Гробницу."}, [165]={npc="Меннит Каркад", tgt="Меннит Каркад", tag="Необязательно", desc="Делайте вместе с маршрутами по северу и югу Серебряного бора, нужно вернуться в Подгород."}, [166]={hint="Убейте Фенвика Татроса и принесите его голову Менниту Каркаду в Квартал Разбойников Подгорода.", tag="Необязательно", desc="Делайте вместе с маршрутами по северу и югу Серебряного бора, нужно вернуться в Подгород."}, [167]={npc="Меннит Каркад", tgt="Меннит Каркад", tag="Необязательно", desc="Делайте вместе с маршрутами по северу и югу Серебряного бора, нужно вернуться в Подгород."}, [168]={npc="Меннит Каркад", tgt="Меннит Каркад", tag="Необязательно", desc="Перед входом в комнату используйте скрытность, чтобы пройти мимо даларанского мага."}, [169]={hint="Отыщите отчет о состоянии Даларана и отдайте его Менниту Каркаду в Квартале Разбойников Подгорода.", tag="Необязательно", desc="Перед входом в комнату используйте скрытность, чтобы пройти мимо даларанского мага."}, [170]={npc="Меннит Каркад", tgt="Меннит Каркад", tag="Необязательно", desc="Перед входом в комнату используйте скрытность, чтобы пройти мимо даларанского мага."}, [171]={npc="Меннит Каркад", tgt="Меннит Каркад", desc="Нежить начинает в Подгороде, затем продолжайте этап вскрытия замков в Кабестане и Лагере Таурахо."}, [172]={npc="Шентул", tgt="Шентул", desc="Нежить начинает в Подгороде, затем продолжайте этап вскрытия замков в Кабестане и Лагере Таурахо."}, [173]={npc="Тюрак Рунический Тотем", tgt="Тюрак Рунический Тотем"}, [174]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [175]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд", desc="Первые две точки — возможные места появления сферы. Получив ее, сразу плывите к Святилищу Ремулоса и используйте ее там."}, [176]={hint="Найдите безделушку святилища в озере Элуны и отнесите ее в святилище Ремулоса на северо-западе Лунной Поляны. Оказавшись там, воспользуйтесь безделушкой.", desc="Первые две точки — возможные места появления сферы. Получив ее, сразу плывите к Святилищу Ремулоса и используйте ее там."}, [177]={npc="Таджарри", tgt="Таджарри", desc="Первые две точки — возможные места появления сферы. Получив ее, сразу плывите к Святилищу Ремулоса и используйте ее там."}, [178]={npc="Таджарри", tgt="Таджарри"}, [179]={hint="Найдите половинку подвески Ловкости водяного облика и половинку подвески Выносливости водяного облика. Поговорите с жителями Лунной поляны, чтобы узнать, где могут находиться эти предметы."}, [180]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [181]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [182]={hint="Возвращайтесь в Громовой Утес и покажите Тюраку Руническому Тотему подвеску Морского Льва."}, [183]={npc="Тюрак Рунический Тотем", tgt="Тюрак Рунический Тотем"}, [184]={npc="Кейн Песнь Пламени", tgt="Кейн Песнь Пламени", tag="Необязательно", desc="Берите вводный квест, проходя через Брилл. Если уже в Подгороде, сразу берите Лавка алхимика."}, [185]={hint="Поговорите с Анастасией Хартвелл.", tag="Необязательно", desc="Берите вводный квест, проходя через Брилл. Если уже в Подгороде, сразу берите Лавка алхимика."}, [186]={npc="Анастасия Хартвелл", tgt="Анастасия Хартвелл", tag="Необязательно", desc="Берите вводный квест, проходя через Брилл. Если уже в Подгороде, сразу берите Лавка алхимика."}, [187]={npc="Анастасия Хартвелл", tgt="Анастасия Хартвелл", desc="Проявите его свитком, бейте, пока существо не перестанет атаковать, затем используйте ларец для духов и подберите контейнер с земли."}, [188]={hint="Возьмите свиток заклинания Проявления и ящик с шкатулками-духоловками за спиной у Анастасии Хартвелл. Принесите 3 заполненных шкатулки-духоловки, ящик со шкатулками духоловками и заклинание Проявления Анастасии в Подгород.", desc="Проявите его свитком, бейте, пока существо не перестанет атаковать, затем используйте ларец для духов и подберите контейнер с земли."}, [189]={npc="Анастасия Хартвелл", tgt="Анастасия Хартвелл", desc="Проявите его свитком, бейте, пока существо не перестанет атаковать, затем используйте ларец для духов и подберите контейнер с земли."}, [190]={npc="Анастасия Хартвелл", tgt="Анастасия Хартвелл"}, [191]={hint="Принесите 10 кусков льна и 6 самоцветов маны Даралана Джозефу Грегориану."}, [192]={npc="Джозеф Грегориан", tgt="Джозеф Грегориан"}, [193]={npc="Джозеф Грегориан", tgt="Джозеф Грегориан", star={"Простые одеяния из чароткани", {"MAGE"}}}, [194]={npc="Джозеф Грегориан", tgt="Джозеф Грегориан", star={"Простые одеяния из чароткани", {"MAGE"}}}, [195]={text="Используйте заранее привязанный камень возвращения, чтобы вернуться в Перекресток. Если камень недоступен, выйдите из Подгорода к башне к югу от Брилла, на западной платформе у Запота (60.74, 58.87) подтвердите рейс в Оргриммар, а из Оргриммара летите в Перекресток."}}},
    ["05-d3"] = {name="Руины Лордерона", entrance="Подгород 72.41, 11.37", pickup="Сначала проверьте у Линнеи в Брилле ход выполнения Патруль в арьергарде. У Линнеи также есть версия Патруль в арьергарде [только орки, нежить]. Перед Серебряным бором, сойдя с дирижабля в Брилле, зайдите к Линнее и Кристофу; в Гробнице сначала возьмите Тревожная просьба у Табиты и завершите Рецептура смерти → Рецептура смерти → Рецептура смерти; в алхимической комнате Подгорода найдите Грейва и Морбина. Эти шесть групп квестов сдаются на этапе подземелья.", pickupS={{"Сначала проверьте у Линнеи в Брилле ход выполнения Патруль в арьергарде"}, {"У Линнеи также есть версия Патруль в арьергарде [только орки, нежить]"}, {"Перед Серебряным бором, сойдя с дирижабля в Брилле, зайдите к Линнее и Кристофу; в Гробнице сначала возьмите Тревожная просьба у Табиты и завершите Рецептура смерти → Рецептура смерти → Рецептура смерти; в алхимической комнате Подгорода найдите Грейва и Морбина"}, {"Эти шесть групп квестов сдаются на этапе подземелья"}}, tips={{k="動線", text="Вход → Сухожвал в Королевском переулке → зачистить нежить по пути → убить Барона и взять герб → Рат'маэль на кладбище; по пути найдите Эдварда на западе. Отрекшиеся на рынке и Виктор у юго-западного дымохода на кладбище необязательны."}, {k="取捨", text="Орда может пройти его на уровнях 16-20. Если вы еще не выполнили цепочку рецептов Серебряного бора, сначала сходите в Гробницу в Серебряном бору, а затем собирайте группу, чтобы засчитался и Сухожвал."}, {k="說明", text="Вход находится в руинах Лордерона над Подгородом, на поверхности Тирисфальских лесов. Используйте координаты карты Подгорода: войдя в руины, поднимитесь по каменной лестнице слева. Не спускайтесь на подземный лифт.", s={{"Вход находится в руинах Лордерона над Подгородом, на поверхности Тирисфальских лесов"}, {"Используйте координаты карты Подгорода: войдя в руины, поднимитесь по каменной лестнице слева"}, {"Не спускайтесь на подземный лифт"}}}}, steps={[1]={npc="Страж смерти Линнея", tgt="Страж смерти Линнея", desc="Если уже выполнено в Брилле, пропустите."}, [2]={hint="Убейте 8 кровоточащих ужасов и 8 странствующих духов, а потом доложите о своих успехах Линнее в ее лагере.", desc="Если уже выполнено в Брилле, пропустите."}, [3]={npc="Страж смерти Линнея", tgt="Страж смерти Линнея", desc="Если уже выполнено в Брилле, пропустите."}, [4]={npc="Страж смерти Линнея", tgt="Страж смерти Линнея", preText="Патруль в арьергарде"}, [5]={hint="Принесите сердце Рвиреза стражу смерти Линнее."}, [6]={npc="Страж смерти Линнея", tgt="Страж смерти Линнея"}, [7]={npc="Страж смерти Кристоф", tgt="Страж смерти Кристоф", desc="У предварительного задания Патруль в арьергарде есть расовые ограничения. Другим расам стоит проверить, предлагает ли Кристоф это задание.", preText="Патруль в арьергарде"}, [8]={npc="Табита Хартвивер", tgt="Табита Хартвивер"}, [9]={npc="Аптекарь Ренферрел", tgt="Аптекарь Ренферрел", desc="Если вы уже начали этот этап в Гробнице, сдавайте по текущему прогрессу, повторять не нужно."}, [10]={hint="Соберите 6 сердец медведя и 6 образцов Летящей крови и принесите их мастеру-аптекарю Фаранеллу в Подгород.", desc="Если вы уже начали этот этап в Гробнице, сдавайте по текущему прогрессу, повторять не нужно."}, [11]={npc="Мастер аптекарь Фаранелл", tgt="Мастер аптекарь Фаранелл", desc="Если вы уже начали этот этап в Гробнице, сдавайте по текущему прогрессу, повторять не нужно."}, [12]={npc="Мастер аптекарь Фаранелл", tgt="Мастер аптекарь Фаранелл", desc="Дневник Бернарда находится в гостинице Деревни Погребальных Костров.", preText="Рецептура смерти"}, [13]={hint="Найдите в деревне Погребальных Костров записи Берарда и отнесите их в Гробницу аптекарю Ренферрелу.", desc="Дневник Бернарда находится в гостинице Деревни Погребальных Костров."}, [14]={npc="Аптекарь Ренферрел", tgt="Аптекарь Ренферрел", desc="Дневник Бернарда находится в гостинице Деревни Погребальных Костров."}, [15]={npc="Аптекарь Ренферрел", tgt="Аптекарь Ренферрел", preText="Рецептура смерти"}, [16]={hint="Принесите 6 образцов мха озерного ползуна, 6 образцов мха озерного тихохода и твердую опухоль мастеру-аптекарю Фаранеллу в Подгород."}, [17]={npc="Мастер аптекарь Фаранелл", tgt="Мастер аптекарь Фаранелл"}, [18]={npc="Теодор Гриффс", tgt="Теодор Гриффс", preText="Рецептура смерти"}, [19]={npc="Морбин Погибель Света", tgt="Морбин Погибель Света"}, [20]={text="Вход: Руины Лордерона"}, [21]={hint="Добудьте крайне токсичный штамм у Сухожвала в руинах Лордерона для Теодора Гриффса из Подгорода.", desc="Место: От входа пройдите зону нерубианцев и найдите патрулирующего Сухожвала в Королевском переулке.", spot="От входа пройдите зону нерубианцев и найдите патрулирующего Сухожвала в Королевском переулке."}, [22]={hint="Добудьте 25 |4сохранившуюся конечность:сохранившиеся конечности:сохранившихся конечностей; в руинах Лордерона и принесите их Морбину Погибель Света в Подгород.", desc="Место: Собирайте добычу с нежити на пути через Королевский переулок, смотровую площадку и кладбище.", spot="Собирайте добычу с нежити на пути через Королевский переулок, смотровую площадку и кладбище."}, [23]={npc="Чудовищная голова", npcObj=true, tag="Требуется внутриигровая проверка", desc="Убив Барона, подберите голову мерзости и сдайте с предмета. После исправления Blizzard от 6 ноября Орда может взять квест с 15 уровня."}, [24]={npc="Герб Лордерона", npcObj=true, tag="Требуется внутриигровая проверка", desc="У Герба Лордерона несколько возможных точек: осмотрите паучий двор, башни и запертые комнаты в поисках интерактивных объектов."}, [25]={hint="Расследуйте исчезновение Эдварда Хартвивера в руинах Лордерона.", desc="Место: Идите к западной стороне кладбища Рат'маэля и подойдите к Эдварду у гулей. Порядок: Лучше сначала выполнить шаг 25, затем подходить к телу.", spot="Идите к западной стороне кладбища Рат'маэля и подойдите к Эдварду у гулей."}, [26]={hint="Убейте Рат'маэля на руинах Лордерона по поручению стража смерти Кристофа из Брилла.", desc="Место: Идите на кладбище Лордерона к Рат'маэлю и расчистите место для боя, прежде чем тянуть.", spot="Идите на кладбище Лордерона к Рат'маэлю и расчистите место для боя, прежде чем тянуть."}, [27]={npc="Теодор Гриффс", tgt="Теодор Гриффс"}, [28]={npc="Морбин Погибель Света", tgt="Морбин Погибель Света"}, [29]={npc="Оран Змеиные Кольца", tgt="Оран Змеиные Кольца"}, [30]={npc="Мастер аптекарь Фаранелл", tgt="Мастер аптекарь Фаранелл"}, [31]={npc="Мастер аптекарь Фаранелл", tgt="Мастер аптекарь Фаранелл", preText="Неизбывные мучения"}, [32]={hint="Принесите голову барона к телу Отмара в Подгород."}, [33]={npc="Недоделанное поганище", tgt="Недоделанное поганище"}, [34]={npc="Недоделанное поганище", tgt="Недоделанное поганище", preText="Неизбывные мучения"}, [35]={hint="Расскажите мастеру аптекарю Фаранеллу в Подгороде о том, что вы узнали."}, [36]={npc="Мастер аптекарь Фаранелл", tgt="Мастер аптекарь Фаранелл"}, [37]={npc="Мастер аптекарь Фаранелл", tgt="Мастер аптекарь Фаранелл", desc="Ядовитый колпак возьмите у Тавена Грейста в Торговом квартале, Жгучую траву — рядом с тренером травников, Эссенцию страдания — у торговца ядами в Квартале Разбойников.", preText="Неизбывные мучения"}, [38]={hint="Добудьте ядовитую черепоганку у Шатенн Гризетт в Торговом квартале, жгуч-траву у наставника травничества и субстанцию агонии у торговца ядами в квартале Разбойников и принесите ингредиенты мастеру аптекарю Фаранеллу в Подгород.", desc="Ядовитый колпак возьмите у Тавена Грейста в Торговом квартале, Жгучую траву — рядом с тренером травников, Эссенцию страдания — у торговца ядами в Квартале Разбойников."}, [39]={npc="Мастер аптекарь Фаранелл", tgt="Мастер аптекарь Фаранелл", desc="Ядовитый колпак возьмите у Тавена Грейста в Торговом квартале, Жгучую траву — рядом с тренером травников, Эссенцию страдания — у торговца ядами в Квартале Разбойников."}, [40]={npc="Мастер аптекарь Фаранелл", tgt="Мастер аптекарь Фаранелл", desc="Введите шипящую сыворотку в устройство над Осмой.", preText="Неизбывные мучения"}, [41]={hint="Введите шипящую сыворотку в механизм над туловищем Отмара по просьбе мастера аптекаря Фаранелла.", desc="Введите шипящую сыворотку в устройство над Осмой."}, [42]={npc="Мастер аптекарь Фаранелл", tgt="Мастер аптекарь Фаранелл", desc="Введите шипящую сыворотку в устройство над Осмой."}, [43]={npc="Страж смерти Кристоф", tgt="Страж смерти Кристоф"}, [44]={npc="Табита Хартвивер", tgt="Табита Хартвивер"}}},
    ["02-10"] = {name="Степи", nameA="Степи: {a:392} & {a:378}", shortA="Степи: {a:392} +", tips={{k="交通", text="Зачистив север, вернитесь в Перекресток по камню возвращения, сначала сдайте квесты лагеря, затем летите в Кабестан. При первом визите в Лагерь Таурахо откройте пункт полета."}, {k="取捨", text="Стоит выполнять вместе пересекающиеся цели Воюющие племена, Ее зовут Ольгра и Огонь ненависти. Для Огонь ненависти нужно 60 бивней, если не хватает, оставьте их в сумке: когда достигнете нужного уровня, отдельная охота не понадобится."}, {k="取捨", text="Квесты Письмо Джин'Зилу и Зиз Физзикс для Когтистых гор сдайте на следующей остановке. Для Яйца мохового паука сейчас соберите яйца, сдайте их при следующем проходе через Кабестан. Большая охота и дополнительный Отчет Песни Войны оставьте для Ясеневого леса."}, {k="取捨", text="Элитного врага РАЗЫСКИВАЕТСЯ: Брууз (20 уровень), событие кентавров Контратака! и пограничный квест Ложное обвинение, очищенное имя делайте с группой. Сопровождение у Крепости Северной Стражи легко притягивает лишних мобов, его можно пропустить."}, {k="取捨", text="«Удача шахтера» выпадает редко, если не выпало, переходите к следующей части маршрута. Четыре редких квеста начинаются только после встречи с редким мобом и подбора предмета."}, {k="提醒", text="Если ниже 23 уровня, у точки «Полевая зачистка» (47.11, 77.38) продолжайте бить ящериц и сталкеров или идите на юг за Ответный удар Ганна. Вход в Пещеры Стенаний примерно 47.70, 35.00, рекомендуется на 18-23 уровнях. Можно взять разблокированные в Перекрестке «Повелители Змей» и «Змеецвет», в порту Кабестана «Неприятности в порту» и «Умный напиток», а на уступе у входа «Шкуры загадочных существ» и «Искоренение Скверны».", s={{"Если ниже 23 уровня, у точки «Полевая зачистка» (47.11, 77.38) продолжайте бить ящериц и сталкеров или идите на юг за Ответный удар Ганна"}, {"Вход в Пещеры Стенаний примерно 47.70, 35.00, рекомендуется на 18-23 уровнях"}, {"Можно взять разблокированные в Перекрестке «Повелители Змей» и «Змеецвет», в порту Кабестана «Неприятности в порту» и «Умный напиток», а на уступе у входа «Шкуры загадочных существ» и «Искоренение Скверны»"}}}}, danger={[1]="Элитный грабитель на «Полевой зачистке» патрулирует среди обычных мобов. Бейте только ящериц по внешнему кругу, не заходите в центр боя.", [2]="На границе с Пылевыми топями много солдат Альянса. Если нет группы, пропустите квест «Ложное обвинение, очищенное имя»."}, grind={[1]={mob="Грозошкур", note="Плотная группа обычных мобов на поле зачистки. Обходите траву по кругу и держитесь подальше от центра боя. Остерегайтесь элитного разъяренного погромщика."}, [2]={mob="Многозубый ловец", note="Плотная группа обычных мобов на том же поле, что и громовые ящерицы. Если рядом чистят другие игроки, бейте других мобов по внешнему кругу и не меняйте лагерь."}}, supply={[1]={npc="Деврак"}, [2]={npc="Брагок"}, [3]={npc="Хозяин таверны Вихлюн"}, [4]={npc="Гразликс"}, [5]={npc="Хозяин таверны Вихлюн"}, [6]={npc="Джаззик"}, [7]={npc="Омуса Громовой Рог"}, [8]={npc="Хозяин таверны Быкко"}, [9]={npc="Шанью Рунический Тотем"}}, steps={[1]={text="Если вы уже вернулись в Перекресток из Гробницы в Серебряном бору, берите квесты в лагере. Если присоединились позже и еще в Восточных королевствах, летите камнем возвращения в Перекресток, а если он недоступен, садитесь на дирижабль в Оргриммар у башни к югу от Брилла и летите в Перекресток. Камень возвращения оставьте до конца северного круга."}, [2]={npc="Манкрик", tgt="Манкрик"}, [3]={npc="Манкрик", tgt="Манкрик"}, [4]={npc="Корран", tgt="Корран"}, [5]={npc="Торк", tgt="Торк"}, [6]={hint="Принесите шкуру Ичияки Сергре Черный Шип на Перекресток."}, [7]={npc="Сергра Черный Шип", tgt="Сергра Черный Шип", desc="Если уже сдан в Перекрестке, пропустите."}, [8]={npc="Сергра Черный Шип", tgt="Сергра Черный Шип"}, [9]={hint="Соберите 6 колец лейтенантов гарпий с душегубок из стаи Зачарованного Крыла и возвращайся к Дарсоку Быстрому Ножу.", desc="Делайте, только если в Перекрестке он не завершен."}, [10]={npc="Дарсок Быстрый Нож", tgt="Дарсок Быстрый Нож", desc="Если уже сдан в Перекрестке, пропустите."}, [11]={npc="Дарсок Быстрый Нож", tgt="Дарсок Быстрый Нож"}, [12]={text="Из Перекрестка летите в Кабестан, если пункты полета уже открыты. Если Кабестан не открыт, идите по большой дороге на восток и откройте его у Брагока (63.08, 37.16). Если квест Самофланж уже взят в Перекрестке, оставьте его."}, [13]={npc="Мебок Миззрикс", tgt="Мебок Миззрикс"}, [14]={npc="Капитан Тало'тас Сияющий", tgt="Капитан Тало'тас Сияющий"}, [15]={npc="Мебок Миззрикс", tgt="Мебок Миззрикс"}, [16]={npc="Пароклапан", tgt="Пароклапан"}, [17]={npc="Управляющий пристанью Головокружилкинc", tgt="Управляющий пристанью Головокружилкинc", tag="Необязательно", desc="Берите, только если по пути заходите в шахту на севере."}, [18]={npc="РАЗЫСКИВАЕТСЯ", npcObj=true, tag="Необязательно", desc="Элитный враг 20 уровня, берите, только если собираетесь в группу."}, [19]={npc="Оператор крана Биггльфузз", tgt="Оператор крана Биггльфузз", tag="Необязательно", desc="Берите, только если собираетесь в Пещеры Стенаний."}, [20]={text="Из Кабестана идите по северному проходу к болоту Пиявка и по пути зачистите северные равнины. Если Самофланж еще не взят, сначала вернитесь к Пароклапану и возьмите его."}, [21]={hint="Получите доступ к терминалу в исследовательском центре Торговой Компании."}, [22]={npc="Панель управления", npcObj=true}, [23]={npc="Панель управления", npcObj=true}, [24]={hint="Закройте топливный распределительный клапан, перепускной клапан и главный клапан управления, а потом снова попытайтесь воспользоваться панелью управления."}, [25]={npc="Панель управления", npcObj=true}, [26]={npc="Панель управления", npcObj=true}, [27]={hint="Возьмите у ремонтника Угрелова ключ от терминала и отоприте им панель управления."}, [28]={npc="Панель управления", npcObj=true}, [29]={npc="Панель управления", npcObj=true}, [30]={hint="Заберите изумруд \"Кошачий глаз\" у одного из надзирателей или головорезов Торговой компании и отдайте его управляющему пристанью Головокружилкинсу в Кабестане.", tag="Необязательно", desc="Изумруд «Кошачий глаз» выпадает редко. Бейте по пути, не задерживайтесь надолго."}, [31]={npc="Крошшер Зизгага", tgt="Крошшер Зизгага", desc="Убейте бригадира, заберите ключ зажигания и отдайте его Виззлкранку."}, [32]={hint="Добыв ключ зажигания, отнесите его Визлкранку.", desc="Убейте бригадира, заберите ключ зажигания и отдайте его Виззлкранку."}, [33]={npc="Крошшер Зизгага", tgt="Крошшер Зизгага", desc="Убейте бригадира, заберите ключ зажигания и отдайте его Виззлкранку."}, [34]={npc="Крошшер Зизгага", tgt="Крошшер Зизгага", desc="Квест запускает сопровождение сразу после взятия. Сначала подлечитесь и зачистите ближайших мобов."}, [35]={hint="Охраняйте Зигзага и похищенный гоблинский резак по пути к Пароклапану в Кабестан.", desc="Сопровождайте из болота Пиявка, дождитесь окончания диалога, чтобы квест засчитался."}, [36]={npc="Кадрак", tgt="Кадрак"}, [37]={npc="Кадрак", tgt="Кадрак", tag="Необязательно", desc="Выполняйте по пути на Заставе Расщепленного Дерева в Ясеневом лесу. Взяв квест, щелкните правой кнопкой по связке донесений, получите отчеты Песни Войны для трех посланников и сохраняйте последний ответ каждого."}, [38]={npc="Вранг Дикозлоб", tgt="Вранг Дикозлоб"}, [39]={npc="Вранг Дикозлоб", tgt="Вранг Дикозлоб"}, [40]={hint="Добудьте 6 шкур равнинного льва у матриархов и патриархов саванны в Степях."}, [41]={hint="Соберите пойманную добычу из 8 сработавших ловушек в Степях."}, [42]={npc="Вранг Дикозлоб", tgt="Вранг Дикозлоб"}, [43]={npc="Вранг Дикозлоб", tgt="Вранг Дикозлоб"}, [44]={npc="Вранг Дикозлоб", tgt="Вранг Дикозлоб"}, [45]={hint="Отнесите связку шкур отшельнику на гряду над Сухими холмами в Степях."}, [46]={npc="Терри Долгопив", tgt="Уолтон"}, [47]={npc="Терри Долгопив", tgt="Уолтон"}, [48]={hint="Отправляйтесь к уничтоженному каравану и узнайте, что нужно култирасцам."}, [49]={npc="Терри Долгопив", tgt="Уолтон"}, [50]={npc="Терри Долгопив", tgt="Уолтон", tag="Необязательно", desc="Когда охрану атакуют, сначала оттяните одиноких моряков. Ждите событие и сдайте квест только после гибели Терри Долгопива."}, [51]={hint="Помогите Уолтону пережить стычку с Терри Долгопивом и култирасскими морпехами.", tag="Необязательно", desc="Когда охрану атакуют, сначала оттяните одиноких моряков. Ждите событие и сдайте квест только после гибели Терри Долгопива."}, [52]={npc="Терри Долгопив", tgt="Уолтон", tag="Необязательно", desc="Когда охрану атакуют, сначала оттяните одиноких моряков. Ждите событие и сдайте квест только после гибели Терри Долгопива."}, [53]={hint="Убейте Серену Кровавое Перо и принесите ее голову Дарсоку Точному Ножу на Перекресток."}, [54]={text="После зачистки севера вернитесь в Перекресток по камню возвращения, а если камень на перезарядке, идите по большой дороге на юг. Сначала сдайте квест Серене и возьмите письмо Джин'Зила, затем летите в Кабестан."}, [55]={npc="Дарсок Быстрый Нож", tgt="Дарсок Быстрый Нож"}, [56]={npc="Дарсок Быстрый Нож", tgt="Дарсок Быстрый Нож", desc="Оставьте до Приюта Солнечного Камня. Джин'Зила ищите в пещере у входа в Когтистые горы."}, [57]={text="После передачи в Перекрестке летите в Кабестан, сдайте Самофланж и северные квесты."}, [58]={npc="Пароклапан", tgt="Пароклапан"}, [59]={npc="Пароклапан", tgt="Пароклапан"}, [60]={npc="Управляющий пристанью Головокружилкинc", tgt="Управляющий пристанью Головокружилкинc", tag="Необязательно"}, [61]={hint="Принесите спинной плавник Брууза Газлоу в Кабестан.", tag="Необязательно", desc="Спускайтесь в воду с группой или подтяните цель к стражам. Главное нанести достаточно урона, чтобы засчитался лут."}, [62]={npc="Газлоу", tgt="Газлоу", tag="Необязательно"}, [63]={text="Юго-восточное побережье, на обратном пути в Лагерь Таурахо возьмите квесты о свинобразах"}, [64]={hint="Верните Газлоу из Кабестана посылку с сапогами и линзу от телескопа.", desc="Выполняйте вместе с Крепостью Северной Стражи. Сначала откройте по сундуку в каждом лагере Южных морей."}, [65]={hint="Капитан Тало'тас Сияющий поручил вам собрать 10 тераморских медалей и убить капитана Гордостанную, канонира Вессана и канонира Смайта."}, [66]={npc="Гилтарес Огненный Цветок", tgt="Гилтарес Огненный Цветок", tag="Необязательно", desc="Начинайте сопровождение, только когда готовы. Сначала закончите башенные пушки и значки."}, [67]={hint="Проводите Гилтареса Огненный Цветок к капитану Сияющему в Кабестан.", tag="Необязательно", desc="Сопроводите Гилтареса от Крепости Северной Стражи до Кабестана и выходите из группы только после того, как квест засчитается."}, [68]={npc="Газлоу", tgt="Газлоу"}, [69]={npc="Капитан Тало'тас Сияющий", tgt="Капитан Тало'тас Сияющий"}, [70]={npc="Капитан Тало'тас Сияющий", tgt="Капитан Тало'тас Сияющий", tag="Необязательно"}, [71]={text="Из Кабестана идите на юго-запад к Застывшему оазису и гнездам рапторов, затем по пути к Лагерю Таурахо."}, [72]={hint="Принесите Регтару Вратам Смерти, живущему на западе от Перекрестка, голову Верога.", desc="С группой зачистка идет быстрее. Услышав крик, идите к палатке в точке 53.06, 41.74."}, [73]={hint="Поохотьтесь на яркочешуйчатых ящеров и соберите с них перья. Отнесите перья в 3 гнезда когтедеров. Возвращайтесь к Сергре Черный Шип в Перекресток."}, [74]={hint="Соберите 5 невредимых рогов ящера с ящерочешуйчатых смертехватов и отнесите их Мебоку Миззриксу в Кабестан."}, [75]={hint="Принесите украденное серебро Газрогу в Перекресток."}, [76]={hint="Отыщите жену Манкрика и возвращайтесь к нему в Перекресток."}, [77]={text="Придя в Лагерь Таурахо, откройте пункт полета у Омуса Громовой Рог (44.45, 59.15), если еще не открыт. Камень возвращения оставьте в Перекрестке до Приюта Солнечного Камня."}, [78]={npc="Кривозуб", tgt="Кривозуб"}, [79]={npc="Таттернак Стальной Горн", tgt="Таттернак Стальной Горн", tag="Необязательно", desc="Берите, только если идете на юг убивать свинобразов."}, [80]={npc="Рубака Логмар", tgt="Рубака Логмар", tag="Необязательно", desc="Групповая цепочка WoW Forever. Пропустите, если не можете сформировать группу."}, [81]={text="Один раз слетайте в Перекресток, сдайте Разъяренные смертехваты, Пропавшая без вести и другие квесты, получите вводный квест Йорна, затем идите на юго-запад бить кентавров или летите обратно в Лагерь Таурахо."}, [82]={npc="Сергра Черный Шип", tgt="Сергра Черный Шип"}, [83]={npc="Газрог", tgt="Газрог"}, [84]={npc="Манкрик", tgt="Манкрик"}, [85]={npc="Манкрик", tgt="Манкрик", desc="Берите только после сдачи Пропавшая без вести."}, [86]={npc="Сергра Черный Шип", tgt="Сергра Черный Шип"}, [87]={npc="Ретгар Врата Смерти", tgt="Ретгар Врата Смерти"}, [88]={npc="Ретгар Врата Смерти", tgt="Ретгар Врата Смерти"}, [89]={hint="Принесите Регтару Вратам Смерти, живущему к западу от Перекрестка, голову Хэрзула."}, [90]={npc="Ретгар Врата Смерти", tgt="Ретгар Врата Смерти"}, [91]={npc="Ретгар Врата Смерти", tgt="Ретгар Врата Смерти", tag="Необязательно", desc="Соберите группу перед взятием, подкрепления кентавров приходят волнами."}, [92]={hint="Принесите кусок знамени Кром'зара Регтару Вратам Смерти. Его можно найти на западе от Перекрестка.", tag="Необязательно", desc="Защитите союзников, убейте полководца Кром'зара и подберите обломок знамени Кром'зара ×1."}, [93]={npc="Ретгар Врата Смерти", tgt="Ретгар Врата Смерти", tag="Необязательно"}, [94]={npc="Джорн Заклинатель Небес", tgt="Джорн Заклинатель Небес"}, [95]={npc="Джорн Заклинатель Небес", tgt="Джорн Заклинатель Небес"}, [96]={text="К югу от Лагеря Таурахо: свинобразы и громовые ящерицы"}, [97]={hint="Убейте 6 водоискателей, 12 терноплетов и 12 геомантов из племени Дыбогривов и возвращайтесь к Кривозубу в Лагерь Таурахо в Степях."}, [98]={hint="Принесите Манкрику с Перекрестка 60 клыков иглосвинов из племени Дыбогривых."}, [99]={hint="Добудьте у свинобразов 4 |4украшение Ольгры:украшения Ольгры:украшений Ольгры; для памятника и принесите Манкрику."}, [100]={hint="Принесите 12 яиц силитидов и вспарывающий коготь Коррану в Перекресток."}, [101]={hint="Убейте солдат Альянса, хозяйничающих на границе Степей и Пылевых топей, а затем возвращайтесь к рубаке Логмару в Лагерь Таурахо.", tag="Необязательно", desc="Сначала оттяните и убейте солдат по отдельности, последним бейте разъяренного погромщика."}, [102]={npc="Копыто Лакота'мани", npcObj=true, tag="Необязательно", desc="Выполняйте, только если встретили редкого Лакота'мани и добыли копыто."}, [103]={npc="Джорн Заклинатель Небес", tgt="Джорн Заклинатель Небес", tag="Необязательно", desc="Выполняйте, только если встретили редкого Лакота'мани и добыли копыто."}, [104]={npc="Хвостовой зубец оватанки", npcObj=true, tag="Необязательно", desc="Выполняйте, только если встретили редкого Оватанку и добыли хвостовой шип."}, [105]={npc="Джорн Заклинатель Небес", tgt="Джорн Заклинатель Небес", tag="Необязательно", desc="Выполняйте, только если встретили редкого Оватанку и добыли хвостовой шип."}, [106]={npc="Голова Жнеца", npcObj=true, tag="Необязательно", desc="Выполняйте, только если встретили редкого Жнеца и добыли голову."}, [107]={npc="Джорн Заклинатель Небес", tgt="Джорн Заклинатель Небес", tag="Необязательно", desc="Выполняйте, только если встретили редкого Жнеца и добыли голову."}, [108]={npc="Перо Ваште Пауни", npcObj=true, tag="Необязательно", desc="Выполняйте, только если встретили редкого Ваште Пауни и добыли перо."}, [109]={npc="Джорн Заклинатель Небес", tgt="Джорн Заклинатель Небес", tag="Необязательно", desc="Выполняйте, только если встретили редкого Ваште Пауни и добыли перо."}, [110]={npc="Кривозуб", tgt="Кривозуб"}, [111]={npc="Кривозуб", tgt="Кривозуб", desc="Если ранее добытый осколок кровавого камня у вас с собой, сдайте его. Иначе добудьте еще один за пределами лагеря."}, [112]={hint="Принесите кровавый осколок Кривозубу в Лагерь Таурахо в Степи.", desc="Если ранее добытый осколок кровавого камня у вас с собой, сдайте его. Иначе добудьте еще один за пределами лагеря."}, [113]={npc="Кривозуб", tgt="Кривозуб", desc="Если ранее добытый осколок кровавого камня у вас с собой, сдайте его. Иначе добудьте еще один за пределами лагеря."}, [114]={npc="Кривозуб", tgt="Кривозуб", tag="Необязательно", desc="Берите, только если идете на юг убивать трех боссов."}, [115]={npc="Рубака Логмар", tgt="Рубака Логмар", tag="Необязательно"}, [116]={text="Если нужен опыт, добавьте дальний юг, затем завершите квесты"}, [117]={hint="Принесите стилет Иглогривых, обгоревший жезл Иглогривых и боевой щит Иглогривых Таттернаку Стальному Горну в Лагерь Таурахо в Степях.", tag="Необязательно"}, [118]={hint="Убейте Нака, Куза и Лока Оркобоя и принесите их черепа Кривозубу в Лагерь Таурахо в Степях.", tag="Необязательно", desc="Три именных моба в разных поселениях, зачищайте по координатам."}, [119]={npc="Ганн Каменное Копье", tgt="Ганн Каменное Копье", tag="Необязательно", desc="Делайте, только если ниже 23 уровня и уже на юге. В лагере зачистите двух видов дворфов и по пути возьмите дневник бригадира."}, [120]={hint="Ганн Каменное Копье попросил вас убить 15 бейл'данских землекопов и 5 бейл'данских старшин.", tag="Необязательно", desc="Делайте, только если ниже 23 уровня и уже на юге. В лагере зачистите двух видов дворфов и по пути возьмите дневник бригадира."}, [121]={npc="Ганн Каменное Копье", tgt="Ганн Каменное Копье", tag="Необязательно", desc="Делайте, только если ниже 23 уровня и уже на юге. В лагере зачистите двух видов дворфов и по пути возьмите дневник бригадира."}, [122]={npc="Сулхаса", tgt="Сулхаса", desc="Сулхаса находится на дереве у границы Пылевых топей."}, [123]={hint="Убейте 7 |4грозового ящера:грозовых ящеров:грозовых ящеров; и 7 |4многозубого ловца:многозубых ловцов:многозубых ловцов; вокруг, чтобы Сулхаса смогла спуститься с дерева."}, [124]={npc="Сулхаса", tgt="Сулхаса"}, [125]={npc="Кривозуб", tgt="Кривозуб", tag="Необязательно"}, [126]={npc="Кривозуб", tgt="Кривозуб", tag="Необязательно", desc="Сдайте по пути, когда вернетесь в Перекресток."}, [127]={npc="Таттернак Стальной Горн", tgt="Таттернак Стальной Горн", tag="Необязательно"}, [128]={text="Завершение цепочки Йорна и двух вводных квестов для следующих остановок"}, [129]={text="По дороге на север от Лагеря Таурахо к западу от Кабестана ищите Быстрогрива и Ишамухала. Получив свежую тушу жевры, сначала используйте ее для приманки Ишамухала."}, [130]={hint="Принесите клык Ишамухала Джорну Искателю Неба в Лагерь Таурахо.", desc="Тушки жевра разлагаются через 30 минут."}, [131]={npc="Мебок Миззрикс", tgt="Мебок Миззрикс"}, [132]={hint="Принесите 5 клыков равнинного льва, 5 почек долгонога и 1 рог рокочущей ящерицы пивовару Дрону в Кабестан.", tag="Необязательно", desc="По пути собирайте львиные клыки, птичьи почки и рога ящерицы. Если не собрали все, можно пропустить."}, [133]={npc="Пивовар Дрон", tgt="Пивовар Дрон", tag="Необязательно"}, [134]={npc="Мебок Миззрикс", tgt="Мебок Миззрикс", tag="Необязательно", desc="Сначала сдайте Рога ящера. Принимайте только в том случае, если вы планируете прогон Пещеры Стенаний."}, [135]={text="Из Кабестана летите в Лагерь Таурахо к Йорну. Если уже 23 уровень и вводную охоту Ясеневого леса делать не нужно, идите из Перекрестка на запад в Когтистые горы."}, [136]={npc="Джорн Заклинатель Небес", tgt="Джорн Заклинатель Небес"}, [137]={npc="Джорн Заклинатель Небес", tgt="Джорн Заклинатель Небес", desc="Сдайте на Заставе Расщепленного Дерева в Ясеневом лесу."}, [138]={npc="Джорн Заклинатель Небес", tgt="Джорн Заклинатель Небес", desc="Выполняйте вместе с громовыми ящерицами за пределами лагеря, заранее запаситесь тремя бутылками."}, [139]={hint="Отнесите 3 порции крови рокочущей ящерицы Джорну Искателю Неба в Лагерь Таурахо.", desc="Выполняйте вместе с громовыми ящерицами за пределами лагеря, заранее запаситесь тремя бутылками."}, [140]={npc="Джорн Заклинатель Небес", tgt="Джорн Заклинатель Небес", desc="Выполняйте вместе с громовыми ящерицами за пределами лагеря, заранее запаситесь тремя бутылками."}, [141]={npc="Джорн Заклинатель Небес", tgt="Джорн Заклинатель Небес"}, [142]={hint="Отыщите и убейте грозового змея. Принесите его крылья Джорну Заклинателю Небес в Лагерь Таурахо."}, [143]={npc="Джорн Заклинатель Небес", tgt="Джорн Заклинатель Небес"}, [144]={text="Вернитесь в Перекресток сдать оставшиеся квесты, затем идите на запад мимо Заставы Чести (35.26, 27.88) в Когтистые горы."}, [145]={npc="Манкрик", tgt="Манкрик"}, [146]={npc="Манкрик", tgt="Манкрик"}, [147]={npc="Корран", tgt="Корран"}, [148]={npc="Торк", tgt="Торк", tag="Необязательно"}, [149]={npc="Сорек", tgt="Сорек", tag="Необязательно", desc="Можно взять у учителя в Оргриммаре, Громовом Утесе или Подгороде. Этот же квест выдают Торм Тотем Гнева (57.24, 87.37) и Балтус Птицелов (47.40, 17.29)."}, [150]={npc="Руга Тотем Гнева", tgt="Руга Тотем Гнева", tag="Необязательно", desc="Можно взять у учителя в Оргриммаре, Громовом Утесе или Подгороде."}, [151]={npc="Руга Тотем Гнева", tgt="Руга Тотем Гнева", tag="Необязательно", desc="Сделайте это вместе с квестами Лагерь Таурахо."}, [152]={hint="Принесите 5 дергающихся усиков Руге Тотему Гнева в Лагерь Таурахо.", tag="Необязательно", desc="Сделайте это вместе с квестами Лагерь Таурахо."}, [153]={npc="Руга Тотем Гнева", tgt="Руга Тотем Гнева", tag="Необязательно", desc="Сделайте это вместе с квестами Лагерь Таурахо."}, [154]={npc="Руга Тотем Гнева", tgt="Руга Тотем Гнева", tag="Необязательно"}, [155]={npc="Тун'грим Огневзор", tgt="Тун'грим Огневзор", tag="Необязательно"}, [156]={npc="Тун'грим Огневзор", tgt="Тун'грим Огневзор", tag="Необязательно", desc="Железные слитки падают с гоблинов в шахте Когтистых гор, азурит с фермеров Хилсбрада, флогистон с босса Лабиринтов Иглошкурых. Слитки можно купить. Сдайте, собрав все, на Заставе Расщепленного Дерева в Ясеневом лесу."}, [157]={npc="Шентул", tgt="Шентул", desc="Остальные расы могут начать с вводного квеста В Оргриммар! в Колючем Холме или сразу взять квест у Шентула."}, [158]={npc="Зандо'зан", tgt="Зандо'зан", desc="Остальные расы могут начать с вводного квеста В Оргриммар! в Колючем Холме или сразу взять квест у Шентула."}, [159]={npc="Зандо'зан", tgt="Зандо'зан"}, [160]={npc="Реникс Презренный", tgt="Реникс Презренный"}, [161]={npc="Реникс Презренный", tgt="Реникс Презренный", desc="Увидев попугая, сначала используйте E.C.A.C. На корабельных сундуках можно потренировать вскрытие замков."}, [162]={hint="Принесите Рениксу Презренному из Кабестана сокровище Южного моря. Не забудьте взять из гизмотронного аппарата Реникса ХОЧУ и отмычки. Они понадобятся для выполнения задания.", desc="Увидев попугая, сначала используйте E.C.A.C. На корабельных сундуках можно потренировать вскрытие замков."}, [163]={npc="Реникс Презренный", tgt="Реникс Презренный", desc="Увидев попугая, сначала используйте E.C.A.C. На корабельных сундуках можно потренировать вскрытие замков."}, [164]={npc="Шентул", tgt="Шентул", desc="Дождитесь, пока Шентул покажет пример, затем выберите его целью и используйте /salute."}, [165]={hint="Повторите приветствие Раздробленной Руки вслед за Шентулом.", desc="Дождитесь, пока Шентул покажет пример, затем выберите его целью и используйте /salute."}, [166]={npc="Шентул", tgt="Шентул", desc="Дождитесь, пока Шентул покажет пример, затем выберите его целью и используйте /salute."}, [167]={npc="Шентул", tgt="Шентул", desc="Сначала запустите две сигнальные ракеты, затем подойдите и используйте /salute. Неправильный порядок приведет к нападению."}, [168]={hint="Отыщите башню Торговой компании к северу от Нефтяного болота и вступите в контакт с тайным агентом Изувеченной Длани, надсмотрщиком Физзулом.", desc="Сначала запустите две сигнальные ракеты, затем подойдите и используйте /salute. Неправильный порядок приведет к нападению."}, [169]={npc="Надсмотрщик Физзул", tgt="Надсмотрщик Физзул", desc="Сначала запустите две сигнальные ракеты, затем подойдите и используйте /salute. Неправильный порядок приведет к нападению."}, [170]={npc="Надсмотрщик Физзул", tgt="Надсмотрщик Физзул", desc="Сначала украдите ключ. Для улучшенного ящика с зельем нужно вскрытие замков. После отравления возьмите «Помощь Хинотта»."}, [171]={hint="Украдите ключ от башни у штейгера Силиксиза, убейте двух мертвяков-мутантов Торговой компании, двух патрульных Торговой компании и двух смотрителей Торговой компании.", desc="Сначала украдите ключ. Для улучшенного ящика с зельем нужно вскрытие замков. После отравления возьмите «Помощь Хинотта»."}, [172]={npc="Шентул", tgt="Шентул", desc="Сначала украдите ключ. Для улучшенного ящика с зельем нужно вскрытие замков. После отравления возьмите «Помощь Хинотта»."}, [173]={npc="Шентул", tgt="Шентул", desc="Сдайте в Мельнице Таррен."}, [174]={npc="Огнир хранитель Огня", tgt="Огнир хранитель Огня", desc="Квесты Зов воды в Громовом Утесе, Зов воды в Колючем Холме и Зов воды в Деревне Кровавого Копыта - необязательные вводные одной цепочки, также можно сразу идти к Ислену Заклинателю Воды."}, [175]={hint="Отыщите в Степях Ислен Заклинательницу Воды.", desc="Квесты Зов воды в Громовом Утесе, Зов воды в Колючем Холме и Зов воды в Деревне Кровавого Копыта - необязательные вводные одной цепочки, также можно сразу идти к Ислену Заклинателю Воды."}, [176]={npc="Ислен Заклинатель Воды", tgt="Ислен Заклинатель Воды", desc="Квесты Зов воды в Громовом Утесе, Зов воды в Колючем Холме и Зов воды в Деревне Кровавого Копыта - необязательные вводные одной цепочки, также можно сразу идти к Ислену Заклинателю Воды."}, [177]={npc="Ислен Заклинатель Воды", tgt="Ислен Заклинатель Воды"}, [178]={hint="Отыщите Брин в южной части Степей."}, [179]={npc="Брин", tgt="Брин"}, [180]={npc="Брин", tgt="Брин"}, [181]={hint="Наполните пустой коричневый бурдюк для воды в источнике ниже хижины Брин и отнесите ей воду."}, [182]={npc="Брин", tgt="Брин"}, [183]={npc="Брин", tgt="Брин", desc="Наберите воду в Мельнице Таррен, сдайте после Заставы Вольного Ветра, вернувшись в Степи."}, [184]={npc="Тюрак Рунический Тотем", tgt="Тюрак Рунический Тотем"}, [185]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [186]={text="Таурены"}, [187]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [188]={npc="Дух Великой Кошки", tgt="Дух Великой Кошки"}, [189]={npc="Дух Великой Кошки", tgt="Дух Великой Кошки"}, [190]={hint="Добудьте реликвию клыка, реликвию когтя и реликвию тихой тени в кельях Малфуриона, а затем отнесите их духу Великой Кошки."}, [191]={npc="Дух Великой Кошки", tgt="Дух Великой Кошки"}, [192]={npc="Дух Великой Кошки", tgt="Дух Великой Кошки"}, [193]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [194]={text="Скайборны из Ваятелей ветра"}, [195]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [196]={npc="Аватара Сэйлинан", tgt="Аватара Сэйлинан"}, [197]={npc="Аватара Сэйлинан", tgt="Аватара Сэйлинан"}, [198]={hint="Добудьте реликвию клыка, реликвию когтя и реликвию тихой тени в кельях Малфуриона, а затем отнесите их аватаре Сэйлинана."}, [199]={npc="Аватара Сэйлинан", tgt="Аватара Сэйлинан"}, [200]={npc="Аватара Сэйлинан", tgt="Аватара Сэйлинан"}, [201]={hint="Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне."}, [202]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [203]={text="Общее завершение для обеих рас"}, [204]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд", desc="Сдайте квест Тюраку Рунический Тотем, чтобы изучить облик кошки и его начальные способности."}, [205]={hint="Вернитесь в Громовой Утес и поговорите с Тюраком Руническим Тотемом на Вершине Старейшин.", desc="Сдайте квест Тюраку Рунический Тотем, чтобы изучить облик кошки и его начальные способности."}, [206]={npc="Тюрак Рунический Тотем", tgt="Тюрак Рунический Тотем", desc="Сдайте квест Тюраку Рунический Тотем, чтобы изучить облик кошки и его начальные способности."}, [207]={npc="Ган'рул Кровавый Глаз", tgt="Ган'рул Кровавый Глаз", desc="После взятия квеста выберите у Казула суккуба или инкуба."}, [208]={npc="Казул", tgt="Казул", d