    [5041] = {n="Снабжение Перекрестка", d="Найдите и верните Торку из Степей ящики с припасами из Перекрестка.", objs={"Ящики с припасами для Перекрестка"}},
    [5049] = {n="Грусть Иеремии", d="Найдите в Подгороде Иеремию Пэйсона и выясните, в самом ли деле он Иеремия Фелстоун. Если да, передайте ему посылку от Джанис Фелстоун."},
