    [5051] = {n="Вторая половина", d="Отыщите вторую половину оберега Удачи на ферме Фелстоун в Западных Чумных землях и соберите его.\nОтдайте оберег Удачи Джанис Фелстоун."},
    [5052] = {n="Кровавые осколки Агамаггана", d="Принесите кровавый осколок Кривозубу в Лагерь Таурахо в Степи.\nСоберите побольше кровавых осколков, и он одарит вас силой, дарованной ему Агамагганом.", tgo={{"Охотник из племени Дыбогривов", "Водоискатель из племени Дыбогривов", "Терноплет из племени Дыбогривов", "Геомант из племени Дыбогривов", "Защитник племени Иглогривых", "Призывательница ветров из стаи Зачарованного Крыла", "Надзиратель Торговой компании", "Ясновидец племени Иглогривых"}}},
