    [5096] = {n="Вылазка в стан Алого Марша", d="Отправляйтесь в лагерь Алого ордена между полем Джанис и Слезами Далсона и уничтожьте командный шатер.\nРазместите в лагере знамя Плети и возвращайтесь к верховному палачу Деррингтону в Бастион, в Западные Чумные земли."},
    [5098] = {n="Сторожевые башни", d="Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен.\nОтметив все четыре башни, следует вернуть сигнальный факел командиру Ашламу Смелонраву в лагерь Холодного Ветра в Западных Чумных землях.", tgo={{"Башня Андорала Один"}, {"Башня Андорала Два"}, {"Башня Андорала Три"}, {"Башня Андорала Четыре"}}},
    [5121] = {n="Верховный вождь племени Зимней Спячки", d="По просьбе Доновы Снегоноры из Зимних Ключей убейте верховного вождя племени Зимней Спячки.", tgo={{"Верховный вождь племени Зимней Спячки"}}},
