    [5155] = {n="Силы Джеденара", d="Отправляйтесь в Джеденар и убейте 4 джеденарских гончих, 4 джеденарских стражей, 6 джеденарских адептов и 6 джеденарских сектантов, затем возвращайтесь к Грете Заиндевевшее Копыто в Оскверненный лес.", tgo={{"Джеденарская гончая"}, {"Джеденарский страж"}, {"Джеденарский адепт"}, {"Джеденаский сектант"}}},
    [5156] = {n="Проверка на порчу", d="Найдите и уничтожьте 2 энтропических зверей и 2 энтропических ужасов при обследовании долины Рваных Ран. После проверьте, по-прежнему ли заполнены кратеры оскверненной водой. Затем возвращайтесь к Таруну Красному Перу в Оскверненный лес.", tgo={{"Энтропический зверь"}, {"Энтропический ужас"}}},
    [5157] = {n="Собрать оскверненную воду", d="Возьмите пустую флягу и наполните ее водой из лунного колодца, что находится в центре Джеденара. Возвращайтесь к Грете Замшелому Копыту в Оскверненный лес.", objs={"Оскверненный Лунный колодец Джеденара"}},
    [5158] = {n="В поисках духовной помощи", d="Отнесите порченую воду из Лунного колодца Ислен Заклинателю Воды в Степи."},
