    [5163] = {n="Йети где-то рядом…", d="Возьмите механического йети Уми и напугайте им ее друзей:\nЛегакки в Круговзоре (Зимние Ключи)\nполивалку в Прибамбасске (Танарис)\nКвикксиля в Укрытии Маршалла (Кратер Ун'Горо)\nКогда проделаете все это, принесите механического йети обратно Уми.", tgo={{"Легакки"}, {"Поливалка"}, {"Квикксиль"}}},
    [5165] = {n="Погасить Пламя Защиты", d="При помощи очищенной воды из лунного колодца загасите пламя в четырех жаровнях защиты внутри Оплота Теней в Оскверненном лесу. Затем возвращайтесь к Грете Замшелому Копыту в Изумрудное святилище.", objs={"Жаровня Боли", "Жаровня Злобы", "Жаровня Страдания", "Жаровня Ненависти"}},
    [5211] = {n="Защитники Дарроушира", d="Освободите 15 духов Дарроушира и возвращайтесь к Карлину Редпату.", tgo={{"Дух Дарроушира"}}},
    [5212] = {n="Плоть не лжет", d="Принесите 20 препаратов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, любая тварь из Стратхольма сойдет за препарат.", tgo={{"Уничтоженный кадавр", "Изуродованный кадавр", "Чумной вурдалак", "Вурдалак-стервятник", "Плотоядный живодер", "Некрорахнид-ползун", "Некрорахнид-живоглот", "Лоскутный ужас"}}},
    [5213] = {n="Вирус чумы", d="Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк.", objs={"Сведения о Плети"}},
    [5214] = {n="Великий Эзра Гримм", d="Найдите табачную лавку Эзры Гримма в Стратхольме, отыщите в ней коробку отличного табака Эзры Гримма и принесите ее Дымку ЛаРу.", tgo={{"Фрас Сиаби"}}},
    [5228] = {n="Котлы Плети", d="Поговорите со жрицей Тьмы Вандис в Бастионе, что в Западных Чумных землях."},
    [5229] = {n="Цель: поле Джанис", d="Отправляйтесь на поле Джанис в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Джанис.", tgo={{"Хранитель котла Желчень"}}},
    [5230] = {n="Возвращение в Бастион", d="Принесите полную бутылку с поля Джанис жрице Тьмы Вандис в Бастион, что в Западных Чумных землях."},
    [5231] = {n="Цель: Слезы Далсона", d="Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона.", tgo={{"Хранитель котла Злобиус"}}},
    [5232] = {n="Возвращение в Бастион", d="Отнесите полную бутылку с поля Слез Далсона жрице Тьмы Вандис в Бастион в Западных Чумных землях."},
    [5233] = {n="Цель: Призрачная ферма", d="Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий.", tgo={{"Хранитель котла Разарх"}}},
    [5234] = {n="Возвращение в Бастион", d="Принесите полную бутылку с Призрачной фермы жрице Тьмы Вандис в Бастион, что в Западных Чумных землях."},
    [5235] = {n="Цель: пустошь Гаррона", d="Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с путоши Гаррона.", tgo={{"Хранитель котла Душегнев"}}},
    [5236] = {n="Возвращение в Бастион", d="Отнесите полную бутылку с пустоши Гаррона жрице Тьмы Вандис в Бастион в Западных Чумных землях."},
    [5238] = {n="Задание выполнено!", star={"Доблестный короткий меч", {"PALADIN", "MAGE", "WARLOCK"}}},
