    [5243] = {n="Святая вода", d="Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Бартоломею Чтимому, как только воды будет достаточно.", objs={"Ящик с припасами", "Стратхольм - ящик с припасами"}},
    [5251] = {n="Архивариус", d="Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алых.", tgo={{"Архивариус Галфорд"}, {}}, objs={"Архив Алых"}},
    [5281] = {n="Мятущиеся души", d="Найдите Эгана. В последний раз его видели недалеко от Стратхольма."},
    [5282] = {n="Мятущиеся души", d="Стреляйте в призраков и неупокоенных на улицах Стратхольма из излучателя Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу.\nОсвободите 15 неупокоенных душ и возвращайтесь к Эгану.", tgo={{"Неупокоенная душа"}}},
    [5306] = {n="Змеекамень Пленяющей Духов", d="Отправляйтесь на Пик Черной горы, убейте Темную охотницу Вос'гаджин. Заберите у нее змеекамень и принесите Килраму.", tgo={{"Темная охотница Вос'гаджин"}}},
    [5341] = {n="Сокровище Баровых", d="Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову.", objs={"Документы на Брилл", "Документы на Каэр Дарроу", "Документы на Южнобережье", "Документы на Мельницу Таррен"}},
    [5361] = {n="Семейное древо", d="Доставьте отчет стража утеса Долгорога Натаке Длинному Рогу на Заставу Скитающихся Духов в Пустоши."},
    [5381] = {n="Рука Ируксоса", d="Добудьте в Крепости Громового Топора Демоническую шкатулку, а затем принесите ее и кирку демонов Тайге Мудрой Гриве в Деревню Ночных Охотников.", tgo={{"Дух демона"}}},
    [5382] = {n="Доктор Теолен Крастинов - Мясник", d="Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф.", tgo={{"Доктор Теолен Крастинов"}, {}, {}}, objs={"Останки Ева Саркофф", "Останки Люсьена Саркофф"}},
    [5386] = {n="Дорога рыбка к обеду", d="Отправляйтесь в Деревню Ночных Охотников и поговорите с Джинар'Зилленом, а затем принесите Натаке Длинному Рогу 2 рыбы-кровобрюха.", tgo={{"Джинар'Зиллен"}}},
    [5441] = {n="Ленивые батраки", d="Проучите ленивых батраков дубинкой старшины. Разбудите 5 батраков, потом верните дубинку штейгеру Тазз'рилу в долине Испытаний.", tgo={{"Ленивый батрак"}}},
    [5481] = {n="Задание Толстяка", d="Соберите 3 ветки мракоцвета для младшего аптекаря Холланда на кладбище Брилла.", objs={"Мракоцвет"}},
    [5482] = {n="Погибельник", d="Соберите 10 веток погибельника для младшего аптекаря Холланда.", objs={"Погибельник"}},
    [5501] = {n="Собиратель костей", d="Принесите 10 костей с Кладбища кодо в хижину Кормека и отдайте Биббли Скобкофузу.", objs={"Кости кодо"}},
    [5511] = {n="Ключ от Некроситета"},
    [5514] = {n="Форма денег стоит", d="Отнесите Кринкелю Сталлинну из Прибамбасска прочные фрагменты скелета и 15 золотых монет."},
    [5518] = {n="Броня огров Гордока", d="Принесите 4 рулона рунной ткани, 8 кусков прочной кожи, 2 мотка рунной нити и огрскую дубильную кислоту Уззлу Наперстяку. Он прикован в секторе Гордока в Забытом Городе.", objs={"Felsteel Chest", "Огрский дубильный чан", "Тайник Уззла Наперстяка"}},
    [5525] = {n="Освободите Нотта!", d="Добыча с: Громила из клана Гордок, Маг-лорд из клана Гордок, Капитан из клана Гордок", tgo={{"Громила из клана Гордок", "Маг-лорд из клана Гордок", "Капитан из клана Гордок", "Чернокнижник из клана Гордок", "Разоритель из клана Гордок", "Стражник Фенгус", "Стражник Слип'кик", "Капитан Давигром"}}},
    [5526] = {n="Осколки сквернита", d="Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Вертоградаря. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне."},
    [5527] = {n="Реликварий Чистоты", d="Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне.", objs={"Пыльный реликварий"}},
