    [5802] = {n="Кузня Пламенного хребта", d="Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.\nОтнесите недоделанную отмычку аптекарю Дитерсу в Бастион, что в Западных Чумных землях.", objs={"Лавовое озеро Пламенного хребта"}},
