    [5848] = {n="Символ семейной любви", d="Отправляйтесь в Статхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину \"Символ семейной любви\", спрятанную за другой, изображающей две луны нашего мира.\nОтнесите картину Тириону Фордрингу.", objs={"Незаконченная картина"}},
