    [7441] = {n="Пузиллин и старейший Аж'Тордин", d="Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина.\nЕсли добудете книгу, вернитесь к Аж'Тордину в павильон Лорисс в Фераласе.", tgo={{"Пузиллин"}}},
    [7461] = {n="Древнее безумие", d="Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется.\nВойдите в Тюрьму Бессмер'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне.\nЕсли задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен'дралар.", tgo={{"Бессмер'тер"}, {"Принц Тортелдрин"}}},
    [7463] = {n="Магический напиток", d="Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари.", tgo={{"Гидротварь"}}},
