    [7602] = {n="Безупречная субстанция Скверны", d="Бесенок из Оскверненного леса просит вас принести ему три порции безупречной субстанции скверны из трех различных мест.\nБезупречной субстанцией в Азшаре владеют сатиры из племени Легаши. В Джеденаре она есть у джеженарских легионеров. Стражи Скверны в Выжженных землях владеют этой субстанцией в своих краях.\nДобудьте три типа безупречной субстанции Скверны и возвращайтесь к Бесенку в Оскверненный лес.", tgo={{"Сатир из племени Легаши", "Разбойник из племени Легаши", "Призыватель огня из племени Легаши", "Legashi Soulstealer", "Призыватель ада из племени Легаши", "Черный страж из племени Легаши"}, {"Джеденарский легионер"}, {"Караульный-страж Скверны"}}},
    [7603] = {n="Огненное ядро Крошиуса", d="Обыщите долину Рваных Ран в Оскверненном лесу и найдите останки Крошиуса. Когда вы их найдете, поднесите к ним пламень Скверны и подождать, пока Крошиус не восстанет из праха. Когда инфернал очнется, убейте его и возьмите из его тела огненное ядро Крошиуса.\nПринесите огненное ядро Крошиуса Ниби Всемогущему в Оскверненный лес.", tgo={{"Крошиус"}, {"Крошиус"}}},
    [7701] = {n="РАЗЫСКИВАЕТСЯ: надзиратель Мальториус", d="Дворф Черного Железа, вероломный надзиратель Мальториус, скрывается в глубине Шлаковой Ямы в Котле, что в Тлеющем ущелье.\nУбейте надзирателя Мальториуса и принесите его голову дозорному капитану Лоло Долгобою.", tgo={{"Надзиратель Мальториус"}}},
    [7721] = {n="Энергия для уменьшения", d="Соберите 10 ядер элементалей воды, убивая морских элементалей и морских валов на Забытом берегу в Фераласе, и принесите их Зорбину Дребезгуну, который находится неподалеку от порта.", tgo={{"Морской элементаль", "Морской вал"}}},
    [7722] = {n="Какой еще плавень?", d="Верните секретные документы по изготовлению огненного плавня, украденные надзирателем Мальториусом. Инспектор скорее всего находится в Шлаковой Яме в Котле. Документы верните мастеру-кузнецу Гориврату в Тлеющем ущелье.", objs={"Секретный рецепт: огненный плавень"}},
    [7723] = {n="Отекшие пальцы", d="По поручению Хансела Большерука убейте 20 тяжелых боевых големов, которых можно найти в землях, окружающих Котел в Тлеющем ущелье. По выполнении задания вернитесь к Ханселу.", tgo={{"Тяжелый боевой голем"}}},
    [7724] = {n="Огненная угроза", d="По указанию Хансела Большерука убейте 20 |4опаляющего лавового паука:опаляющих лавовых пауков:опаляющих лавовых пауков; в Тлеющем ущелье. Пауки водятся на вулканических плато и в озерах лавы в Тлеющем ущелье.\nКогда убьете достаточно пауков, вернитесь к Ханселу в Тлеющее ущелье.", tgo={{"Опаляющий лавовый паук"}}},
    [7727] = {n="Пламезавры? Ну и название...", d="По поручению Хансела Большерука убейте 20 пламезавров, обитающих в озерах лавы в Шлаковой Яме - это часть Котла в Тлеющем ущелье.\nПо выполнении задания вернитесь к Ханселу в Тлеющее ущелье.", tgo={{"Пламезавр"}}},
    [7728] = {n="УКРАДЕНО: фурма и подзорная труба наблюдателя", d="Найдите и верните фурму и подзорную трубу наблюдателя надсмотрщику Скренджу в Тлеющем ущелье. Единственная известная информация: вещи были украдены дворфами Черного Железа. Подзорная труба является бесценным прибором для наблюдения, а фурма - незаменимым кузнечным инструментом.", tgo={{"Кузнец из клана Черного Железа"}, {"Наблюдатель из клана Черного Железа"}}},
    [7729] = {n="ВАКАНСИЯ: устранитель конкурентов", d="Убейте 15 надсмотрщиков и 15 поработителей из клана Черного Железа. По выполнении задания вернитесь к десятнику Скренджу в Тлеющее ущелье.", tgo={{"Надсмотрщик из клана Черного Железа"}, {"Поработитель из клана Черного Железа"}}},
    [7730] = {n="Вторжение улья Цуккаш", d="Принесите 20 панцирей Цуккаш Хадокену Быстрому Страннику в Лагерь Мохаче в Фераласе.", tgo={{"Острожал из улья Цуккаш", "Оса из улья Цуккаш", "Рабочий из улья Зуккаш", "Проходчик из улья Зуккаш", "Жалохвост"}}},
    [7731] = {n="Жалохвост", d="Убейте жалохвоста в Гудящей Бездне и принести железы ядохлеста Хадокену Быстрому Страннику в Лагерь Мохаче в Фераласе.", tgo={{"Жалохвост"}}},
    [7732] = {n="Донесение об улье Цуккаш", d="Доставьте отчет о нашествии насекомых-Цуккаш на Лагерь Мохаче Зилзибину Барабанному Бою, который проживает на Волоке в Оргриммаре."},
    [7734] = {n="Борьба за качество", d="Принесите 10 шкур йети из пещеры Бешеного оврага Джангору Быстрому Страннику в Лагерь Мохаче в Фераласе.", tgo={{"Йети из пещеры Бешеного оврага", "Старейшина Бешеного оврага", "Лютый йети со Свирепого Утеса", "Крадущийся йети со Свирепого Утеса"}}},
    [7738] = {n="Безупречная шкура йети", d="Отнесите безупречную шкуру йети Джангору Быстрому Страннику в Лагерь Мохаче в Фераласе."},
    [7761] = {n="Приказ Чернорука", d="Вот уж действительно идиот... Похоже, вам нужно найти это клеймо и выжечь на руке метку Драккисата, чтобы получить доступ к сфере Приказа.\nВ письме ясно сказано, что генерал Драккисат охраняет клеймо. Наверное, стоит проверить."},
    [7815] = {n="Хрустогрызы, чувак!", d="Убейте 15 морских хрустогрызов по поручению Катума Удильщика из деревни Сломанного Клыка во Внутренних землях.", tgo={{"Морской хрустогрыз"}}},
    [7816] = {n="Гаммерита!", d="Убейте Гаммериту и верните Катуму Удильщику из деревни Сломанного Клыка его лучшую блесну.\nКатум сказал, что Гаммерита ползает по берегу среди остальных черепах.", tgo={{"Гаммерита"}}},
    [7828] = {n="Охота на бродяг", d="Убейте 15 среброгривых бродяг и 15 среброгривых ревунов по поручению охотника Мархора из деревни Сломанного Клыка во Внутренних землях.\nМархор сказал, что волки обирают в лесах Внутренних земель.", tgo={{"Среброгривый бродяга"}, {"Среброгривый ревун"}}},
    [7829] = {n="Охота на дикарей", d="Убейте 20 диких совухов по поручению охотника Мархора из деревни Сломанного Клыка во Внутренних землях.\nМархор сказал, что совухи обитают в лесах Внутренних земель.", tgo={{"Дикий совух"}}},
    [7830] = {n="Отмщение за погибших", d="Убейте остроклюва-повелителя небес и принесите его перо охотнику Мархору в деревню Сломанного Клыка.\nМархор говорил, что остроклюв водятся во Внутренних землях.", tgo={{"Остроклюв-повелитель небес"}}},
    [7839] = {n="Хулиганы Порочной Ветви", d="Найдите потерянные инструменты кузнеца Углежога из деревни Сломанного Клыка во Внутренних землях.\nУглежог сказал, что инструменты могут быть в одном из храмов троллей Порочной Ветви в северо-восточной части Внутренних земель. Также следует проверить на Осклизлой скале.", objs={"Потерянные инструменты Шлакодрева"}},
    [7840] = {n="Лярд потерял свой обед", d="Найдите обед Лярда из деревни Сломанного Клыка во Внутренних землях.\nЛярд сказал, что потерял свой обед на острове к северу, где могут встретиться тролли из клана Порочной Ветви.", tgo={{"Похититель из племени Порочной Ветви"}}},
    [7845] = {n="Похищен старейшина Сломанный Клык!", d="Спасите старейшину Сломанного Клыка из Джинта'Алора по поручению его жены из деревни Сломанного Клыка.\nСтарейшину держат в плену на самом верху Джинта'Алор - главного поселения троллей из клана Порочной Ветви, расположенного на юге Внутренних земель."},
    [7846] = {n="Отыщите ключ!", d="Убейте хранительницу Хита'йю и заберите у нее ключ от оков, после чего возвращайтесь к старейшине Сломанному Клыку в Джинта'Алор и освободите его.", tgo={{"Хита'йа Хранительница"}}},
    [7847] = {n="Возвращение к старейшине племени Сломанного Клыка", d="Возвращайтесь к старейшине Сломанному Клыку и сообщите ей, что ее муж спасен."},
    [7848] = {n="Сродство с недрами", d="Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте фрагмент ядра. Принесите его Лотосу Хранителю Портала к Черной горе.", objs={"Осколок из Огненных Недр"}},
    [7849] = {n="Воссоединение останков", d="Принесите охотнику Мархору из деревни Сломанного Клыка во Внутренних землях кости и череп его брата-близнеца.\nМархор сказал, что останки его брата бросили на съедение слизнюкам и волкам Порочной Ветви - все эти твари водятся неподалеку от вершины Джинта'Алор: слизнюки в компостной яме, а волки - в логове.", objs={"Груда черепов", "Груда костей"}},
    [7850] = {n="Темные сосуды", d="Принесите 10 сосудов с порченой кровью старейшине племени Сломанного Клыка во Внутренние земли. Сосуды с кровью находятся в поселении Джинта'Алор.", objs={"Сосуд с порченой кровью"}},
    [7861] = {n="РАЗЫСКИВАЕТСЯ: коварная жрица Ведьмиса и ее прислужники", d="Убейте коварную жрицу Ведьмису и 20 стражей Аман'заси из клана Порочной Ветви, после чего доложите старейшине племени Сломанного Клыка в Деревне Сломанного Клыка.\nКоварную жрицу Ведьмису и стражей Аман'заси можно найти в верхней части Джинта'Алора во Внутренних землях.", tgo={{"Коварная жрица Ведьмиса"}, {"Страж Аман'заси из племени Порочной Ветви"}}},
    [7862] = {n="Требуется: капитан стражи в деревню Сломанного Клыка", d="Убейте 20 берсерков, 20 темных охотников, 20 кровопийц и 20 пожирателей душ из племени Порочной Ветви.\nПосле выполнения задания вернуться к старейшине Сломанному Клыку во Внутренних землях.", tgo={{"Берсерк из племени Порочной Ветви"}, {"Темный охотник из племени Порочной Ветви"}, {"Кровопийца из племени Порочной Ветви"}, {"Пожиратель душ из племени Порочной Ветви"}}, star={"Руна капитана стражи", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}},
    [7877] = {n="Сокровище Шен'дралар", d="Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!"},
    [8151] = {n="Талисман охотника", d="Поговорите с Огтинком из Азшары."},
    [8153] = {n="Рога и копыта", d="Принесите пару великолепных рогов мохоногого оленя Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", tgo={{"Мохоногий олень"}}},
    [8231] = {n="Охота на волномета", d="Принесите 6 чешуй волношлепа Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", tgo={{"Молодой волношлеп", "Волношлеп", "Большой волношлеп"}}},
    [8232] = {n="Зеленый дракон", d="Принесите зуб Морфаза Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", tgo={{"Морфаз"}}, star={"Глаз девизавра", {"HUNTER"}}},
    [8233] = {n="Приглашение", d="Поговорите с лордом Джорахом Черным Вороном в его поместье."},
    [8234] = {n="Запечатанная лазурная сумка", d="Добудьте запечатанную лазурную сумку у шамана из племени Древобрюхов в Азшаре. Затем отнесите сумку верховному магу Ксилему в Азшаре.", tgo={{"Шаман из племени Древобрюхов", "Шаман из клана Черночревов"}}},
    [8235] = {n="Зашифрованные фрагменты", d="Принесите 10 зашифрованных фрагментов верховному магу Ксилему в Азшару.", tgo={{"Лесной слизнюк"}}},
