    [8250] = {n="Магическое искусство", d="Найдите Саната Лим-Йо и добейтесь, чтобы он доставил вас к верховному магу Ксилему."},
    [8251] = {n="Волшебная пыль", d="Принесите 10 горстей сияющей пыли верховному магу Ксилему.", tgo={{"Эльф крови-геодезист", "Эльф крови-землемер", "Эльф крови-защитник", "Эльф крови - чародей", "Эвин Шмидт", "Люмина Песнь Ветра"}}},
    [8252] = {n="Кораллы сирен", d="Соберите 6 заколдованных кораллов и принесите их верховному магу Ксилему.", tgo={{"Сирена из клана Бича Злобы"}}},
    [8253] = {n="Уничтожить Морфаза", d="Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему.", tgo={{"Морфаз"}}, star={"Огненный рубин", {"MAGE"}}},
