    [8256] = {n="Лимфа нежити", d="Принесите лимфу нежити Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", tgo={{"Зомби Занзила", "Охотник Занзила", "Скелет-живодер", "Скелет-колдун", "Скелет-ужасень", "Скелет-палач", "Скелет-вождь", "Скелет-послушник"}}},
