    [8276] = {n="Отвоевание Силитуса", d="Поговорите с призывательницей ветров Гордый Рог в крепости Кенария."},
    [8277] = {n="Смертельный яд", d="Принесите Битиссе Шаткобрус из крепости Кенария 8 жал камнехвостых скорпидов и 8 жвал песчаных пауков-быстроногов.", tgo={{"Камнехвостый скорпид"}, {"Песчаный паук-быстроног"}}},
    [8278] = {n="Последняя надежда Ноггла", d="Принесите Битиссе Шаткобрус из крепости Кенария 3 жала камнехвостых клешневиков, 3 жала камнехвостых живодеров и 3 клыка скальных пауков-скакунов.", tgo={{"Камнехвостый живодер"}, {"Камнехвостый клешневик"}, {"Скальный паук-скакун"}}},
    [8280] = {n="Надежные поставки", d="Убейте 15 землечерпов по поручению призывательницы ветров Гордый Рог.", tgo={{"Землечерп"}}},
    [8281] = {n="Обеспечение безопасности", d="Убейте 20 земляных сокрушителей по поручению призывательницы ветров Гордый Рог.", tgo={{"Земляной сокрушитель"}}},
    [8284] = {n="Сумеречная тайна", d="Геолог Ехидная из крепости Кенария просит вас собрать 8 фрагментов сумеречной таблички.", objs={"Фрагмент Сумеречной таблички"}},
    [8285] = {n="Дезертир", d="Отнесите восстановленную табличку отшельнику Ортеллу в Силитус."},
    [8318] = {n="Тайные послания", d="Принесите 10 зашифрованных Сумрачных текстов Бору Буйногривому в крепость Кенария.", tgo={{"Хранитель Хавунт из культа Сумеречного Молота", "Мститель из культа Сумеречного Молота", "Геолорд из культа Сумеречного Молота", "Камнезов из культа Сумеречного Молота", "Мастер из культа Сумеречного Молота", "Владыка Эверан из культа Сумеречного Молота", "Пламехват из культа Сумеречного Молота", "Властитель культа Сумеречного Молота"}}},
